style.css:
@-moz-document domain("roblox.com") {
body {
        background: url("https://i.imgur.com/xyz123.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Optional: Make Roblox content containers transparent */
    #header, .content, .footer, .game-page, .container-main, .navbar {
        background: transparent !important;
    }
}
